-- Table: masterdata_supplier
-- Source: accounting_admin_db.sql (1. Master data)
--
-- One migration per table. Do not edit this file after it has been applied;
-- add a new migration for later schema changes.

CREATE TABLE IF NOT EXISTS masterdata_supplier (
    id              BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    supplier_code   VARCHAR(30)  NOT NULL UNIQUE,
    company_name    VARCHAR(150) NOT NULL,
    contact_person  VARCHAR(100),
    email           VARCHAR(255),
    phone           VARCHAR(50),
    address         TEXT,
    city            VARCHAR(100),
    npwp            VARCHAR(50),
    payment_term_id BIGINT REFERENCES masterdata_payment_term(id),
    notes           TEXT,
    status          VARCHAR(20)  NOT NULL DEFAULT 'active'
                    CHECK (status IN ('active', 'inactive')),
    created_at      TIMESTAMPTZ  NOT NULL DEFAULT now(),
    updated_at      TIMESTAMPTZ  NOT NULL DEFAULT now()
);
